begin;
create table if not exists public.aderencia_formularios(id bigint generated by default as identity primary key,titulo text not null check(length(trim(titulo)) between 3 and 150),ativo boolean not null default false,criado_em timestamptz not null default now());
create table if not exists public.aderencia_respostas(formulario_id bigint references public.aderencia_formularios(id) on delete cascade,professor_id uuid references public.perfis(id),disciplinas bigint[] not null check(cardinality(disciplinas) between 1 and 6),dias smallint not null check(dias between 1 and 6),atualizado_em timestamptz not null default now(),primary key(formulario_id,professor_id));
alter table public.aderencia_formularios enable row level security;
alter table public.aderencia_respostas enable row level security;
create policy aderencia_coord_form on public.aderencia_formularios for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
create policy aderencia_docente_form on public.aderencia_formularios for select to authenticated using(ativo and exists(select 1 from public.perfis where id=auth.uid() and ativo and papel='professor'));
create policy aderencia_leitura on public.aderencia_respostas for select to authenticated using(public.usuario_e_coordenador() or professor_id=auth.uid());
grant select,insert,update on public.aderencia_formularios to authenticated;
grant usage,select on sequence public.aderencia_formularios_id_seq to authenticated;
grant select on public.aderencia_respostas to authenticated;
revoke all on public.aderencia_formularios,public.aderencia_respostas from anon;
create or replace function public.salvar_aderencia_docente(p_formulario bigint,p_disciplinas bigint[],p_dias integer) returns void language plpgsql security definer set search_path=public as $$
begin
 if not exists(select 1 from public.perfis where id=auth.uid() and ativo and papel='professor') then raise exception 'Acesso exclusivo de docentes ativos.';end if;
 perform 1 from public.aderencia_formularios where id=p_formulario and ativo for share;
 if not found then raise exception 'O formulário está fechado.';end if;
 if p_dias is null or p_dias not between 1 and 6 or p_disciplinas is null or cardinality(p_disciplinas) not between 1 and 6 then raise exception 'Selecione de 1 a 6 disciplinas e informe de 1 a 6 dias.';end if;
 if (select count(distinct d.id) from public.matriz_disciplinas d where d.id=any(p_disciplinas) and d.ativa and d.curso in ('ADS','EDC'))<>cardinality(p_disciplinas) then raise exception 'Disciplinas inválidas ou duplicadas.';end if;
 insert into public.aderencia_respostas values(p_formulario,auth.uid(),p_disciplinas,p_dias,now())
 on conflict(formulario_id,professor_id) do update set disciplinas=excluded.disciplinas,dias=excluded.dias,atualizado_em=now();
end $$;
revoke all on function public.salvar_aderencia_docente(bigint,bigint[],integer) from public;
grant execute on function public.salvar_aderencia_docente(bigint,bigint[],integer) to authenticated;
commit;
